add_action( 'woocommerce_before_calculate_totals', 'perfectpixel_sync_cart_quantities', 5 );

function perfectpixel_sync_cart_quantities( $cart ) {
	static $running = false;
	$master_id = (int) '{{sync_master_product}}';
	if ( $running || ! $master_id || ( is_admin() && ! wp_doing_ajax() ) ) {
		return;
	}
	$quantity = 0;
	foreach ( $cart->get_cart() as $item ) {
		if ( (int) $item['product_id'] === $master_id ) {
			$quantity = (int) $item['quantity'];
			break;
		}
	}
	if ( ! $quantity ) {
		return;
	}
	$running = true;
	foreach ( $cart->get_cart() as $key => $item ) {
		if ( (int) $item['product_id'] !== $master_id && (int) $item['quantity'] !== $quantity ) {
			$cart->cart_contents[ $key ]['quantity'] = $quantity;
		}
	}
	$running = false;
}
